  const ago = iso => { const h=Math.max(0,Math.floor((Date.now()-new Date(iso).getTime())/36e5));return h<1?'Agora há pouco':h<24?`Há ${h}h`:h<48?'Ontem':`Há ${Math.floor(h/24)} dias`; };
